  onCategoryClick(catName: string) {

    G.getCourseCategory().subscribe(
      res => {
        res.forEach(cat => {
          if (cat.title === catName) {
            this.router
              .navigate(
                ['Home', 'Search'],
                {
                  queryParams:
                  {
                    categoryIds: [cat.courseCategoryId]
                  }
                });
            return;
          }
        });
      }
    );
  }

  totalVideoTime(): string {

    let time = '00:00';
    let h = 0;
    let m = 0;
    let s = 0;

    this.selectedCourse.courseVideos.forEach(vid => {

      if (vid.videoTime != null && vid.videoTime != '00:00') {
        const str = vid.videoTime.split(':', 2);

        m += +str[0];
        s += +str[1];
      }
    });

    if (s >= 60) {
      m += Math.floor(s / 60);
      s = (s % 60);
    }

    if (m >= 60) {
      h += Math.floor(m / 60);
      m = (m % 60);
    }

    time = h.toString() + ':' + m.toString() + ':' + s.toString();

    return time;
  }

